#!ibl edition=2
$out = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-18_76회차/ai/base"
$rows = zip($a, $b) >> [table:each]{
  $x = $it[0]
  $y = $it[1]
  assert $x.id == $y.id, "행 순서 불일치", {a:$x.id,b:$y.id}
  $es = $y.evidence_status
  $st = ($es == null ? "unknown" : ($es.comparison == "content" and $es.checked > 0 ? $es.state : "unknown"))
  return {id:$x.id,path:$x.path,source:{path:$x.path,start_line:$x.start_line,end_line:$x.end_line,numbered:$x.numbered,total_lines:$x.total_lines,observation_ref:$x.observation_ref},
    excerpt:$x.excerpt,claim:$x.claim,claim_status:"사용자 선언 — 정확성 미검증",note_id:$y.note_id,
    note_locus_matches_path:$y.locus_ok,note_prior_class:$y.prior_class,note_generalizes:$y.generalizes,
    state:$st,evidence_status:$es}
}
$g = $rows >> [table:groupby]{by:"state",agg:{count:["count"]}}
$cm = from_entries($g >> [table:each]{ return [$it.state,$it.count] })
$counts = {unchanged:get($cm,"unchanged",0),changed:get($cm,"changed",0),missing:get($cm,"missing",0),unknown:get($cm,"unknown",0),total:len($rows)}
assert $counts.unchanged + $counts.changed + $counts.missing + $counts.unknown == len($rows), "합계 불일치", $counts
$limits = [
  "claim은 명부의 사용자 선언을 옮긴 것이며 그 의미 정확성은 검증하지 않았다.",
  "content 현재성은 지정 범위(1~3줄, sha256_utf8_lines)만 대조했다. scope.complete=false — 파일의 나머지 줄은 설명하지 않는다.",
  "receipt_availability=not_checked — 대조 시점에 관측 영수증 원본의 보존 여부는 따로 검사되지 않았다.",
  "검사 시각(checked_at) 이후 자료가 바뀌면 상태는 달라질 수 있다.",
  "단언 문서(evidence_doc)는 파일 locus가 아닌 상위 outputs/memory.md에 그려진다(문서 위치 규칙). 단언의 locus 자체는 각 입력 파일이다."
]
$report = {title:"76회차 시스템 인수 검토표",manifest:"/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-18_76회차/inputs/ai/manifest.json",rows:$rows,counts:$counts,limits:$limits}
$w1 = [self:write]{path:f"${$out}/report.json",content:json($report)}
[def:행md]($r) {
  $ex = $r.excerpt >> strip
  $o = $r.evidence_status == null ? {} : $r.evidence_status.outcomes[0]
  return f"""## ${$r.id}
- 출처: `${$r.path}` ${$r.source.start_line}~${$r.source.end_line}줄 (전체 ${$r.source.total_lines}줄, numbered=${json($r.source.numbered)})
- 읽기 관측 영수증: `${$r.source.observation_ref}`
- claim (사용자 선언 — 정확성 미검증): ${$r.claim}
- note_id: ${$r.note_id} (locus=입력 파일 일치: ${json($r.note_locus_matches_path)}, prior_class=${$r.note_prior_class}, generalizes=${json($r.note_generalizes)})
- 현재성: **${$r.state}** — comparison=${get($r.evidence_status,"comparison")}, checked=${get($r.evidence_status,"checked")}, unchecked=${get($r.evidence_status,"unchecked")}, method=${get($o,"method")}, reason=${get($o,"reason")}, 영수증=${json(get($o,"observation_ref"))}, 범위=${json(get($o,"scope"))}, checked_at=${get($r.evidence_status,"checked_at")}

```text
${$ex}
```
"""
}
$body = $rows >> [table:each]{ [fn:행md]{r:$it} }
$table = $rows >> [table:each]{ return f"| ${$it.id} | `${split($it.path,"/")[-1]}` | ${$it.source.start_line}~${$it.source.end_line} | ${json($it.source.numbered)} | ${$it.note_id} | ${$it.state} |" }
$md = f"""# 76회차 시스템 인수 검토표

명부: `${$report.manifest}`

> claim은 원천에 대한 사용자 선언이다. 이 검토는 그 정확성을 검증하지 않았다.

| id | 파일 | 줄 | numbered | note_id | 현재성 |
|---|---|---|---|---|---|
${join($table,"\n")}

## 합계
unchanged ${$counts.unchanged} · changed ${$counts.changed} · missing ${$counts.missing} · unknown ${$counts.unknown} · 합 ${$counts.total}

${join($body,"\n")}
## 미확인 한계
${join($limits >> [table:each]{ return f"- ${$it}" },"\n")}
"""
$w2 = [self:write]{path:f"${$out}/report.md",content:$md}
$rj = [self:read]{path:f"${$out}/report.json"}
$rm = [self:read]{path:f"${$out}/report.md"}
$d = $rj.data
$ids = $d.rows >> [table:each]{ return $it.id }
$chk = {
  ids_order:$ids == ["D1","D2","D3","D4","D5","D6"],
  excerpts_equal:all(zip($d.rows,$rows) >> [table:each]{ return $it[0].excerpt == $it[1].excerpt }),
  numbered_ok:all($d.rows >> [table:each]{ return $it.source.numbered == starts_with_num($it.excerpt) }),
  counts_sum:$d.counts.unchanged + $d.counts.changed + $d.counts.missing + $d.counts.unknown == len($d.rows),
  counts_equal:$d.counts == $counts,
  md_has_all_ids:all($ids >> [table:each]{ return contains($rm.text,f"## ${$it}") }),
  md_has_disclaimer:contains($rm.text,"정확성을 검증하지 않았다"),
  md_has_limits:contains($rm.text,"## 미확인 한계"),
  md_has_sum:contains($rm.text,f"합 ${$counts.total}")
}
return {counts:$counts,checks:$chk,w1:$w1.path,w2:$w2.path}
